import json
COMMON=("Take the face and identity from photo 1 (same woman: long wavy chestnut brown hair with lighter sun highlights, hazel-brown eyes, freckles across nose and cheeks). Do NOT copy its big smile: use the expression below. Take the body exactly from photo 2 and keep it the same size: toned athletic hourglass, narrow waist, natural bust exactly as full as photo 2 and not enlarged, curvy hips, not skinny, not heavier than photo 2. Her skin is a golden sun-kissed tan exactly like the reference, warm, not pale. Raw unretouched amateur phone photo taken by a friend, no beauty filter, no smoothing, no airbrushing, visible pores, tiny freckles, uneven skin tone, flyaway hair strands, matte not glossy, flat ordinary light, warm soft evening lamp light, low contrast, phone noise. Camera at eye level, face fully in frame with generous headroom above her head, face not tiny, shot from head to upper thighs, front-facing with shoulders square to camera, she is alone in an empty plain bedroom with a plain wall behind her, no other people, no text or logos anywhere. EXPRESSION: closed-mouth knowing smirk, one eyebrow slightly raised, looking straight into the camera.")
S={
"sfw":"Scene: getting ready for a night out after the football, standing in her bedroom wearing a fitted plain red scoop-neck t-shirt and dark jeans, hair half pinned up, holding a big chunky mug of strong dark-brown builder's tea in one hand at chest height.",
"x":"Scene: getting ready for a night out after the football, standing in her bedroom wearing a small red triangle bikini top and matching red high-cut bikini bottoms, hair half pinned up, holding a big chunky mug of strong dark-brown builder's tea in one hand at chest height."}
json.dump({k:v+" "+COMMON for k,v in S.items()},open('prompts.json','w'),indent=1)
